import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Spaced Practice","description":"","frontmatter":{},"headers":[],"relativePath":"learning/spaced-practice.md","filePath":"learning/spaced-practice.md"}'),c={name:"learning/spaced-practice.md"};function o(g,n,r,e,l,u){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="spaced-practice" tabindex="-1">Spaced Practice <a class="header-anchor" href="#spaced-practice" aria-label="Permalink to &quot;Spaced Practice&quot;">​</a></h1><p>Trên trang này# Spaced Practice — học giãn cách <a href="#spaced-practice-—-hoc-gian-cach">​</a> Cùng một lượng thời gian học, chia ra nhiều buổi cách xa nhau, tạo ra trí nhớ bền hơn hẳn so với dồn vào một buổi. Khoảng nghỉ giữa các buổi không phải thời gian lãng phí — nó là một phần của cơ chế.</p><h2 id="hoc-don-hoat-đong-—-trong-48-gio-​" tabindex="-1">Học dồn hoạt động — trong 48 giờ <a href="#hoc-don-hoat-đong-—-trong-48-gio">​</a> <a class="header-anchor" href="#hoc-don-hoat-đong-—-trong-48-gio-​" aria-label="Permalink to &quot;Học dồn hoạt động — trong 48 giờ [​](#hoc-don-hoat-đong-—-trong-48-gio)&quot;">​</a></h2><p>Ôn suốt đêm trước kỳ thi thật sự có tác dụng cho kỳ thi đó. Vấn đề là gần như toàn bộ nội dung biến mất trong vòng vài ngày sau. Với một bài kiểm tra 15 phút thì không sao. Với một môn mà kiến thức lớp 8 là nền cho lớp 9, đây là thảm hoạ trả chậm. Đây là lý do rất nhiều học sinh &quot;học tốt&quot; ở từng bài kiểm tra nhưng hổng nền nghiêm trọng khi lên cấp: mỗi chương được học dồn, thi xong, rồi rơi.</p><h2 id="vi-sao-khoang-nghi-lai-giup-​" tabindex="-1">Vì sao khoảng nghỉ lại giúp <a href="#vi-sao-khoang-nghi-lai-giup">​</a> <a class="header-anchor" href="#vi-sao-khoang-nghi-lai-giup-​" aria-label="Permalink to &quot;Vì sao khoảng nghỉ lại giúp [​](#vi-sao-khoang-nghi-lai-giup)&quot;">​</a></h2><p>Nghịch lý ở chỗ: <strong>quên một phần rồi nhớ lại mới là thứ tạo ra trí nhớ bền</strong>. Nhớ lại khi nội dung vẫn còn tươi thì quá dễ và củng cố được rất ít. Nhớ lại khi ký ức đã mờ đi một chút đòi hỏi nỗ lực thật, và chính nỗ lực đó làm ký ức bền hơn. Điều đó dẫn tới một nguyên tắc phản trực giác: <strong>buổi ôn hiệu quả nhất diễn ra ngay trước lúc bạn sắp quên</strong> — không sớm hơn.</p><h2 id="khoang-cach-gian-dan-​" tabindex="-1">Khoảng cách giãn dần <a href="#khoang-cach-gian-dan">​</a> <a class="header-anchor" href="#khoang-cach-gian-dan-​" aria-label="Permalink to &quot;Khoảng cách giãn dần [​](#khoang-cach-gian-dan)&quot;">​</a></h2><p>Mỗi lần nhớ lại thành công, kiến thức bám lâu hơn, nên lần ôn kế tiếp có thể để xa hơn: textChuỗi này không cố định. Nemo12 tính khoảng cách từ mức vững thực tế của learner và từ việc lần nhớ lại vừa rồi khó hay dễ:</p><ul><li>Nhớ lại <strong>dễ dàng sau một khoảng dài</strong> → kiến thức đang rất ổn định, đẩy lần ôn sau ra xa hơn nữa.</li><li>Nhớ lại <strong>trượt</strong> → khoảng cách co lại, và hệ thống điều chỉnh ước lượng tốc độ quên cho riêng learner ở mảng đó. Nói cách khác: ôn càng hiệu quả thì càng ít phải ôn. Đây là chỗ đối nghịch hoàn toàn với logic &quot;ôn càng nhiều càng chắc&quot;.</li></ul><h2 id="nemo12-khong-tao-ra-no-on-tap-​" tabindex="-1">Nemo12 không tạo ra nợ ôn tập <a href="#nemo12-khong-tao-ra-no-on-tap">​</a> <a class="header-anchor" href="#nemo12-khong-tao-ra-no-on-tap-​" aria-label="Permalink to &quot;Nemo12 không tạo ra nợ ôn tập [​](#nemo12-khong-tao-ra-no-on-tap)&quot;">​</a></h2><p>Đây là điểm thiết kế mà chúng tôi coi trọng. Các hệ thống ôn tập giãn cách thường có một lỗi nghiêm trọng: learner nghỉ một tuần, quay lại thấy <strong>&quot;187 bài quá hạn&quot;</strong>. Cảm giác nợ nần đó là lý do phổ biến nhất khiến người ta bỏ hẳn. Nemo12 làm khác: danh sách ôn được <strong>tính lại từ đầu mỗi ngày</strong>, không phải một hàng đợi tồn đọng. Câu hỏi mỗi sáng không phải &quot;còn nợ bao nhiêu&quot; mà là <em>&quot;trong tất cả những thứ đã mờ đi, hôm nay ôn cái nào là đáng nhất?&quot;</em>. Một số thứ sẽ bị bỏ qua hẳn — vì chúng không còn phục vụ mục tiêu nào của learner nữa. Đó là quyết định đúng, không phải thiếu sót. Ngoài ra, hệ thống ghi nhận cả <strong>ôn tập ngầm</strong>: khi con làm một bài mới có dùng tới kiến thức cũ và dùng đúng, kiến thức cũ đó được tính là vừa được nhớ lại. Không cần một buổi ôn riêng cho nó. Ôn không đồng nghĩa với học lại từ đầu Tuỳ mức độ mờ, &quot;ôn&quot; có thể là một câu hỏi duy nhất (30 giây), hai ba bài trộn lẫn (5 phút), hoặc quay lại từ bài mẫu (20 phút). Mở lại cả chương chỉ vì &quot;lâu rồi chưa xem&quot; gần như luôn là lãng phí.</p><h2 id="o-nha-​" tabindex="-1">Ở nhà <a href="#o-nha">​</a> <a class="header-anchor" href="#o-nha-​" aria-label="Permalink to &quot;Ở nhà [​](#o-nha)&quot;">​</a></h2><p>Điều hữu ích nhất một gia đình có thể làm không phải là tăng giờ học, mà là <strong>rải nó ra</strong>. Bốn buổi 25 phút trong tuần tốt hơn hẳn một buổi hai tiếng cuối tuần — cùng thời lượng, kết quả rất khác. Và khi con nói &quot;phần này con học rồi mà&quot;, câu trả lời hữu ích là: <em>&quot;Ừ, mình kiểm tra xem còn nhớ không thôi.&quot;</em> Học rồi và còn nhớ là hai chuyện khác nhau — <a href="/decisions/retention">Nemo12 lưu chúng thành hai con số riêng biệt</a>. Học dồn thi tốt hôm sau. Học giãn cách còn dùng được sau ba năm. <a href="/learning/hoc-ky">&#39;Học kỹ&#39; nghĩa là gì, và dừng ở đâu →</a></p>',13)])])}const p=h(c,[["render",o]]);export{s as __pageData,p as default};
